#pragma once
/*#
    # z80.h -- edge-stepped variant with pin-accurate bus timing

    A cycle-stepped Z80 emulator in a C header, stepped on every clock EDGE
    (twice per T-state), with the pins following the Zilog Z80 bus timing
    diagrams (Z80 CPU User Manual UM0080, Z84C00 data sheet) at half-clock
    resolution.

    ALTERED VERSION: this file is a modified version of z80.h from
    https://github.com/floooh/chips (commit ee88c35), altered in October 2026
    (by Claude Code, for antirez) for pin-accurate, half-clock bus timing.
    It is NOT the original software. Instruction behaviour, flags, MEMPTR
    (WZ), R increments and the number of T-states of every instruction and of
    the interrupt / NMI responses are unchanged from the original core; what
    changed is WHEN pins are driven and inputs are sampled, plus the RES,
    BUSRQ/BUSAK, CLK, DOE and AOE pins. The file is generated by the altered
    codegen/z80_gen.py from codegen/z80_desc.yml.

    Do this:
    ~~~C
    #define CHIPS_IMPL
    ~~~
    before you include this file in *one* C or C++ file to create the
    implementation.

    Optionally provide
    ~~~C
    #define CHIPS_ASSERT(x) your_own_asset_macro(x)
    ~~~

    ## Emulated Pins
    ***********************************
    *           +-----------+         *
    * CLK   --->|           |---> A0  *
    * M1    <---|           |---> A1  *
    * MREQ  <---|           |---> A2  *
    * IORQ  <---|           |---> ..  *
    * RD    <---|           |---> A15 *
    * WR    <---|    Z80    |         *
    * RFSH  <---|           |<--> D0  *
    * HALT  <---|           |<--> D1  *
    * WAIT  --->|           |<--> ... *
    * INT   --->|           |<--> D7  *
    * NMI   --->|           |         *
    * RES   --->|           |---> DOE (CPU drives D0..D7)    *
    * BUSRQ --->|           |---> AOE (CPU drives A0..A15,   *
    * BUSAK <---|           |     MREQ, IORQ, RD, WR)        *
    *           +-----------+         *
    ***********************************

    All control pins are 'active high' bits in the pin mask: a set bit means
    the (active-low) line is asserted, e.g. Z80_MREQ set == /MREQ is low.

    ## The clock-edge contract (see README.md for the full edge-by-edge table)

    The board calls z80_tick() on every clock edge, with Z80_CLK in the
    passed pin mask set to the clock level AFTER the edge:

    ~~~C
        pins = z80_tick(&cpu, pins | Z80_CLK);   // rising edge: 'H' half of a T-state
        ...answer the bus...
        pins = z80_tick(&cpu, pins & ~Z80_CLK);  // falling edge: 'L' half
        ...answer the bus...
    ~~~

    A call where Z80_CLK did not change is not an edge, the CPU only updates
    its inputs (and the NMI edge latch). The returned pins are the CPU
    outputs for the half-cycle which begins with that edge (A0..A15, D0..D7
    while Z80_DOE is set, M1, MREQ, IORQ, RD, WR, RFSH, HALT, BUSAK, DOE,
    AOE, RETI) plus an echo of the inputs. CPU outputs are taken from the CPU
    state, not from the passed pins, so the board may pass in pins built from
    scratch (only D0..D7, WAIT, INT, NMI, RES, BUSRQ, CLK are read).

    Inputs are sampled where the real CPU samples them:

    - opcode fetch (M1): opcode sampled at the rising edge of T3
    - memory read: data sampled at the falling edge of T3
    - IO read: data sampled at the falling edge of T3
    - interrupt acknowledge: vector sampled at the rising edge of T3
    - WAIT: falling edge of T2 (memory and opcode fetch cycles), of the
      automatic TW (IO cycles), of the second automatic TW (interrupt ack),
      and again at the falling edge of each inserted wait state
    - INT, BUSRQ: rising edge of the last T-state of an instruction (INT)
      or machine cycle (BUSRQ)
    - NMI: falling edge of /NMI, latched at any time, then sampled like INT
    - RES: every rising edge; while active the CPU is held in reset

    The board must put read data on D0..D7 before the sampling edge, i.e.
    pass it into the z80_tick() call for that edge. A board which answers
    combinationally (put mem[addr] on D whenever MREQ+RD is returned) works.

    ## Functions

    ~~~C
    uint64_t z80_init(z80_t* cpu);
    ~~~
        Initializes a new z80_t instance, returns the initial pin mask. The
        first rising clock edge starts the opcode fetch at address 0. (A
        board can also hold RES active for a few clocks instead.)

    ~~~C
    uint64_t z80_reset(z80_t* cpu)
    ~~~
        Immediately resets the z80_t instance (like z80_init, but keeps the
        pin inputs), the next rising edge starts executing at address 0.

    ~~~C
    uint64_t z80_tick(z80_t* cpu, uint64_t pins)
    ~~~
        Process one clock edge (see above).

    ~~~C
    uint64_t z80_prefetch(z80_t* cpu, uint16_t new_pc)
    ~~~
        Force execution to continue at a specific PC, the next rising edge
        starts the opcode fetch at new_pc. Only call this between
        instructions (e.g. when z80_opdone() is true or right after init).

    ~~~C
    bool z80_opdone(z80_t* cpu)
    ~~~
        True right after the rising clock edge which started the opcode fetch
        of the next instruction (all effects of the previous instruction are
        visible in the CPU registers).

    ## HOWTO

    A minimal board with 64 KB RAM and an IO port handler:
    ~~~C
        uint8_t mem[1<<16];
        z80_t cpu;
        uint64_t pins = z80_init(&cpu);
        while (!done) {
            pins ^= Z80_CLK;                    // next clock edge
            pins = z80_tick(&cpu, pins);
            if ((pins & (Z80_MREQ|Z80_RD)) == (Z80_MREQ|Z80_RD)) {
                Z80_SET_DATA(pins, mem[Z80_GET_ADDR(pins)]);
            }
            else if ((pins & (Z80_MREQ|Z80_WR)) == (Z80_MREQ|Z80_WR)) {
                mem[Z80_GET_ADDR(pins)] = Z80_GET_DATA(pins);
            }
            else if ((pins & (Z80_IORQ|Z80_M1)) == (Z80_IORQ|Z80_M1)) {
                Z80_SET_DATA(pins, interrupt_vector);
            }
            else if ((pins & (Z80_IORQ|Z80_RD)) == (Z80_IORQ|Z80_RD)) {
                Z80_SET_DATA(pins, io_read(Z80_GET_ADDR(pins)));
            }
            else if ((pins & (Z80_IORQ|Z80_WR)) == (Z80_IORQ|Z80_WR)) {
                io_write(Z80_GET_ADDR(pins), Z80_GET_DATA(pins)); // called on several edges!
            }
        }
    ~~~
    Note that unlike the original z80.h, a control pin combination is now
    active for several consecutive half-cycles (e.g. MREQ+RD from the falling
    edge of T1 to the falling edge of T3), side effects of IO writes must be
    edge-detected by the board (e.g. on the IORQ+WR rising/falling transition).

    The daisy chain IEIO pin is passed through, RETI is set for one half
    cycle (from the falling edge of T3 of the first stack read of RETI to
    the next rising edge).
#*/
