        case Z80_DDFD_M1_T1L: _ctl(Z80_M1|Z80_MREQ|Z80_RD); _fgoto(Z80_DDFD_M1_T2H);
        case Z80_DDFD_M1_T2H: _rgoto(Z80_DDFD_M1_T2L);
        case Z80_DDFD_M1_T2L: _wait(Z80_DDFD_M1_T2H); _fgoto(Z80_DDFD_M1_T3H);
        case Z80_DDFD_M1_T3H: cpu->opcode = _gd(); pins = _z80_refresh(cpu, pins); _rgoto(Z80_DDFD_M1_T3L);
