        case Z80_CB_M1_T1L: _ctl(Z80_M1|Z80_MREQ|Z80_RD); _fgoto(Z80_CB_M1_T2H);
        case Z80_CB_M1_T2H: _rgoto(Z80_CB_M1_T2L);
